SELECT

FROM api_keys ak
JOIN workspaces w ON w.uuid = ak.workspace_uuid
LEFT JOIN users u ON u.uuid = ak.created_by_user_uuid
WHERE w.organization_uuid = #{organizationUUID}
AND ak.external_id = #{externalID}

SELECT ak.created_at, ak.uuid
FROM api_keys ak
JOIN workspaces w ON w.uuid = ak.workspace_uuid
WHERE w.organization_uuid = #{organizationUUID}
AND ak.external_id = #{externalID}

SELECT

FROM api_keys ak
JOIN workspaces w ON w.uuid = ak.workspace_uuid
LEFT JOIN users u ON u.uuid = ak.created_by_user_uuid

    w.organization_uuid = #{organizationUUID}

        AND w.external_id = #{workspaceExternalID}


        AND u.external_id = #{createdByUserExternalID}


        AND ak.status = #{status}




                AND (ak.created_at, ak.uuid) > (#{anchor.CreatedAt}, #{anchor.UUID})


                AND (ak.created_at, ak.uuid) < (#{anchor.CreatedAt}, #{anchor.UUID})






        ORDER BY ak.created_at ASC, ak.uuid ASC


        ORDER BY ak.created_at DESC, ak.uuid DESC


LIMIT #{limit}
